"""Optional systemd and launchd unit text.

These files are for hosts that already run those managers. The supervisor never
invokes systemctl or launchctl, and it does not require either one.
"""

from __future__ import annotations

import shlex
from pathlib import Path
from xml.sax.saxutils import escape

from .spec import ServiceSpec

_NOTE = (
    "Generated by avrone-svc. Optional integration for a host that already has "
    "this service manager. Avrone runs these processes itself and does not "
    "require systemd or launchd."
)


def render_systemd(spec: ServiceSpec) -> str:
    after = ["network-online.target"]
    wants = []
    for dep in spec.depends_on:
        unit = f"avrone-{_safe(dep)}.service"
        after.append(unit)
        wants.append(unit)
    lines = [
        f"# {_NOTE}",
        "[Unit]",
        f"Description={spec.description or spec.name}",
        "After=" + " ".join(after),
    ]
    if wants:
        lines.append("Wants=" + " ".join(wants))
    restart = {"always": "always", "on-failure": "on-failure", "never": "no"}[spec.restart]
    lines.extend([
        "",
        "[Service]",
        "Type=simple",
        f"ExecStart={_systemd_command(spec.command)}",
        f"Restart={restart}",
        f"RestartSec={spec.backoff_initial_seconds:g}",
        f"TimeoutStopSec={spec.stop_grace_seconds:g}",
        "KillMode=mixed",
    ])
    if spec.cwd:
        lines.append(f"WorkingDirectory={spec.cwd}")
    if spec.user:
        lines.append(f"User={spec.user}")
    for key, value in sorted(spec.env.items()):
        lines.append(f"Environment={key}={value}")
    if spec.runtime_limit_seconds:
        lines.append(f"RuntimeMaxSec={spec.runtime_limit_seconds:g}")
    lines.extend(["", "[Install]", "WantedBy=multi-user.target", ""])
    return "\n".join(lines)


def render_launchd(spec: ServiceSpec) -> str:
    label = f"dev.avrone.{_safe(spec.name)}"
    args = "\n".join(f"      <string>{escape(part)}</string>" for part in spec.command)
    env = "\n".join(
        f"      <key>{escape(key)}</key>\n      <string>{escape(value)}</string>"
        for key, value in sorted(spec.env.items())
    )
    if spec.restart == "always":
        keep = "  <key>KeepAlive</key>\n  <true/>"
    elif spec.restart == "on-failure":
        keep = (
            "  <key>KeepAlive</key>\n  <dict>\n"
            "    <key>SuccessfulExit</key>\n    <false/>\n  </dict>"
        )
    else:
        keep = "  <key>KeepAlive</key>\n  <false/>"
    cwd = ""
    if spec.cwd:
        cwd = f"  <key>WorkingDirectory</key>\n  <string>{escape(spec.cwd)}</string>\n"
    user = ""
    if spec.user:
        user = f"  <key>UserName</key>\n  <string>{escape(spec.user)}</string>\n"
    env_block = f"  <key>EnvironmentVariables</key>\n  <dict>\n{env}\n  </dict>\n" if env else ""
    return (
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
        "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" "
        "\"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
        "<plist version=\"1.0\">\n<dict>\n"
        f"  <key>Label</key>\n  <string>{label}</string>\n"
        f"  <key>Comment</key>\n  <string>{escape(_NOTE)}</string>\n"
        "  <key>ProgramArguments</key>\n  <array>\n"
        f"{args}\n  </array>\n"
        f"{cwd}{user}{env_block}{keep}\n"
        "  <key>RunAtLoad</key>\n  <true/>\n"
        "</dict>\n</plist>\n"
    )


def write_units(specs: list[ServiceSpec], kind: str, out_dir: Path) -> list[Path]:
    if kind not in {"systemd", "launchd"}:
        raise ValueError("kind must be systemd or launchd")
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    written = []
    if kind == "systemd":
        names = " ".join(f"avrone-{_safe(spec.name)}.service" for spec in specs if spec.enabled)
        target = out_dir / "avrone-svc.target"
        target.write_text(
            f"# {_NOTE}\n[Unit]\nDescription=Avrone services (optional systemd integration)\n"
            f"Wants={names}\n",
            encoding="utf-8",
        )
        written.append(target)
    for spec in specs:
        if kind == "systemd":
            path = out_dir / f"avrone-{_safe(spec.name)}.service"
            path.write_text(render_systemd(spec), encoding="utf-8")
        else:
            path = out_dir / f"dev.avrone.{_safe(spec.name)}.plist"
            path.write_text(render_launchd(spec), encoding="utf-8")
        written.append(path)
    return written


def _systemd_command(command: list[str]) -> str:
    return " ".join(shlex.quote(part) for part in command)


def _safe(name: str) -> str:
    return "".join(ch if ch.isalnum() or ch in "-_" else "-" for ch in name)
